(function(){
'use strict';
var sheet=document.getElementById('sheet');
function toast(msg){var t=document.createElement('div');t.textContent=msg;Object.assign(t.style,{position:'fixed',left:'50%',bottom:'28px',transform:'translateX(-50%)',zIndex:'999999',background:'#2d2924',color:'#fff',padding:'10px 16px',borderRadius:'8px',fontSize:'12px',boxShadow:'0 8px 28px #0003'});document.body.appendChild(t);setTimeout(function(){t.remove()},1800)}
function filename(){try{var s=JSON.parse(localStorage.getItem('welog-pair-sheet-v4')||'{}');return((s.pairName||'WeLog').trim()||'WeLog')+'.png'}catch(e){return'WeLog.png'}}
function saveBlob(blob){if(!blob)throw new Error('empty PNG blob');var url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename();document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},4000)}
async function viaHtmlToImage(){if(!window.htmlToImage||!window.htmlToImage.toBlob)throw new Error('html-to-image unavailable');var rect=sheet.getBoundingClientRect();return await window.htmlToImage.toBlob(sheet,{cacheBust:true,pixelRatio:2,backgroundColor:'#ffffff',width:Math.ceil(rect.width),height:Math.ceil(rect.height),style:{margin:'0',transform:'none'}})}
async function viaCanvas(){if(!window.html2canvas)throw new Error('html2canvas unavailable');var rect=sheet.getBoundingClientRect();var canvas=await window.html2canvas(sheet,{scale:2,useCORS:true,allowTaint:true,backgroundColor:'#ffffff',logging:false,imageTimeout:30000,width:Math.ceil(rect.width),height:Math.ceil(rect.height),scrollX:-window.scrollX,scrollY:-window.scrollY});return await new Promise(function(resolve){canvas.toBlob(resolve,'image/png')})}
async function save(){var btn=document.getElementById('printBtn');if(!btn||!sheet)return;var text=btn.textContent;btn.disabled=true;btn.textContent='저장 중…';try{if(document.fonts&&document.fonts.ready)await document.fonts.ready;await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})});var blob;try{blob=await viaHtmlToImage()}catch(primary){console.warn('html-to-image failed, falling back',primary);blob=await viaCanvas()}saveBlob(blob);toast('PNG 저장이 완료되었습니다!')}catch(err){console.error('WeLog PNG export failed:',err);alert('PNG 저장에 실패했습니다. 개발자 콘솔의 오류를 확인해 주세요.')}finally{btn.disabled=false;btn.textContent=text}}
function install(){var old=document.getElementById('printBtn');if(!old)return;var b=old.cloneNode(true);old.replaceWith(b);b.id='printBtn';b.addEventListener('click',function(e){e.preventDefault();e.stopImmediatePropagation();save()},true)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else install();
})();